CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, display_name text NOT NULL, role text NOT NULL CHECK (role IN ('student','mentor','counsellor','interviewer','admin','data-steward')), date_of_birth date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id), roll_number text UNIQUE NOT NULL, course_code text NOT NULL, batch text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enrolments (student_id uuid REFERENCES students(id), course_code text NOT NULL, semester text NOT NULL, PRIMARY KEY(student_id, course_code, semester));
CREATE TABLE IF NOT EXISTS governance_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), config_key text NOT NULL, version integer NOT NULL, value jsonb NOT NULL, approved boolean NOT NULL DEFAULT false, required boolean NOT NULL DEFAULT true, approved_by uuid REFERENCES users(id), approved_at timestamptz, UNIQUE(config_key, version));
CREATE TABLE IF NOT EXISTS consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id), purpose text NOT NULL CHECK (purpose IN ('attendance_marks_sharing','interview_recording','interview_feedback_counsellor_sharing')), status text NOT NULL CHECK (status IN ('granted','denied','withdrawn')), text_version integer NOT NULL, approved_version boolean NOT NULL, granted_at timestamptz, withdrawn_at timestamptz);
CREATE TABLE IF NOT EXISTS attendance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id), attended_on date NOT NULL, status text NOT NULL CHECK (status IN ('present','absent','excused')), reason text, recorded_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assessment_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id), subject text NOT NULL, assessment_name text NOT NULL, score numeric(5,2) NOT NULL CHECK (score >= 0 AND score <= 100), assessed_at date NOT NULL, recorded_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS mentor_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id), mentor_id uuid NOT NULL REFERENCES users(id), observation text NOT NULL, observed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id), rule_key text NOT NULL, rule_version integer NOT NULL, explanation text NOT NULL, status text NOT NULL DEFAULT 'pending_review' CHECK (status IN ('pending_review','reviewed','dismissed','support_started')), reviewed_by uuid REFERENCES users(id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS interventions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id), flag_id uuid REFERENCES risk_flags(id), owner_id uuid REFERENCES users(id), plan text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS follow_ups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intervention_id uuid NOT NULL REFERENCES interventions(id), due_on date NOT NULL, notes text, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS outcomes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intervention_id uuid NOT NULL REFERENCES interventions(id), summary text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS interviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id), interviewer_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL CHECK (kind IN ('mock','real')), status text NOT NULL DEFAULT 'scheduled', scheduled_start timestamptz NOT NULL, scheduled_end timestamptz NOT NULL, google_event_url text, provider_room_id text, recording_key text, recording_consent_id uuid REFERENCES consents(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS interview_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), interview_id uuid UNIQUE NOT NULL REFERENCES interviews(id), interviewer_id uuid NOT NULL REFERENCES users(id), communication_score integer CHECK (communication_score BETWEEN 1 AND 5), communication_comment text NOT NULL, technical_score integer CHECK (technical_score BETWEEN 1 AND 5), technical_comment text NOT NULL, problem_solving_score integer CHECK (problem_solving_score BETWEEN 1 AND 5), problem_solving_comment text NOT NULL, confidence_score integer CHECK (confidence_score BETWEEN 1 AND 5), confidence_comment text NOT NULL, overall_comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE IF NOT EXISTS notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), uploader_id uuid NOT NULL REFERENCES users(id), subject_id uuid REFERENCES subjects(id), course_code text NOT NULL, semester text NOT NULL, unit text NOT NULL, title text NOT NULL, object_key text NOT NULL, file_size bigint NOT NULL, mime_type text NOT NULL, download_allowed boolean NOT NULL DEFAULT false, scan_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS note_bookmarks (student_id uuid REFERENCES students(id), note_id uuid REFERENCES notes(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(student_id, note_id));
CREATE TABLE IF NOT EXISTS note_access_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), note_id uuid NOT NULL REFERENCES notes(id), user_id uuid NOT NULL REFERENCES users(id), action text NOT NULL CHECK(action IN ('view','download')), occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_id uuid REFERENCES subjects(id), unit text NOT NULL, topic text NOT NULL, difficulty text NOT NULL, question_type text NOT NULL CHECK(question_type IN ('mcq','short_answer','long_answer')), prompt text NOT NULL, options jsonb, correct_answer text, explanation text NOT NULL, rubric jsonb, created_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_id uuid REFERENCES subjects(id), name text NOT NULL, mode text NOT NULL CHECK(mode IN ('mid_term','end_term','topic_quiz')), duration_seconds integer NOT NULL, published boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS exam_questions (exam_id uuid REFERENCES exams(id), question_id uuid REFERENCES questions(id), position integer NOT NULL, PRIMARY KEY(exam_id, question_id));
CREATE TABLE IF NOT EXISTS exam_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exams(id), student_id uuid NOT NULL REFERENCES students(id), status text NOT NULL DEFAULT 'active', started_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, score numeric(5,2));
CREATE TABLE IF NOT EXISTS answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exam_attempts(id), question_id uuid NOT NULL REFERENCES questions(id), answer_text text, is_correct boolean, awarded_marks numeric(5,2), time_spent_seconds integer NOT NULL DEFAULT 0, saved_at timestamptz NOT NULL DEFAULT now(), UNIQUE(attempt_id, question_id));
CREATE TABLE IF NOT EXISTS results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid UNIQUE NOT NULL REFERENCES exam_attempts(id), topic_summary jsonb NOT NULL DEFAULT '{}', question_explanations jsonb NOT NULL DEFAULT '{}', weak_topic_reasons jsonb NOT NULL DEFAULT '[]', generated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, actor_user_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id text, outcome text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pseudonym_mappings (pseudonym_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid UNIQUE NOT NULL REFERENCES students(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_log_occurred_at_idx ON audit_log(occurred_at);
CREATE INDEX IF NOT EXISTS attendance_student_date_idx ON attendance_records(student_id, attended_on);
CREATE INDEX IF NOT EXISTS consent_student_purpose_idx ON consents(student_id, purpose, status);
